// Normalize the Gmail trigger output (works with "Simplify" on or off)
const s = $('Settings').first().json;
const max = Number(s.max_body_chars) || 6000;
// (Settings replaces the item, so read the emails straight from the trigger node)
return $('Gmail Trigger').all().map(item => {
  const m = item.json;
  const fromAddr = m.from?.value?.[0]?.address || m.From || m.from?.text || '';
  const fromName = m.from?.value?.[0]?.name || '';
  const body = (m.text || m.snippet || '').toString().replace(/\n{3,}/g, '\n\n').slice(0, max);
  return { json: {
    messageId: m.id, threadId: m.threadId,
    from: fromAddr, fromName,
    subject: m.subject || m.Subject || '(no subject)',
    body, date: m.date || new Date().toISOString(),
  }};
});

// Parse the model's JSON. Anything invalid falls back to "other" so nothing is lost.
const CATS = ['urgent','to_reply','newsletter_spam','other'];
const emails = $('Prepare Email').all();
return $input.all().map((item, i) => {
  const r = item.json;
  let out = r?.output?.[0]?.content?.[0]?.text ?? r?.message?.content ?? r?.text ?? r;
  if (typeof out === 'string') {
    try { out = JSON.parse(out.replace(/^```(json)?|```$/g, '').trim()); } catch (e) { out = {}; }
  }
  out = out || {};
  const ok = CATS.includes(out.category);
  return { json: { ...emails[i].json,
    category: ok ? out.category : 'other',
    summary: String(out.summary || '').slice(0, 300),
    fallback: !ok } };
});

// Missing labels plus any missing parent labels (e.g. "AI" for "AI/Lead"), parents first.
function missingWithParents(names, byName) {
  const out = [];
  for (const n of names) {
    const parts = String(n || '').split('/').map(x => x.trim()).filter(Boolean);
    for (let i = 1; i <= parts.length; i++) {
      const p = parts.slice(0, i).join('/');
      if (!byName[p.toLowerCase()] && !out.some(x => x.toLowerCase() === p.toLowerCase())) out.push(p);
    }
  }
  return out.sort((a, b) => a.split('/').length - b.split('/').length);
}
// Map category -> Gmail label ID, e.g. "AI/Urgent". Missing labels are listed in labelsToCreate.
const s = $('Settings').first().json;
const prefix = s.label_prefix ?? 'AI/';
const NAMES = { urgent:'Urgent', to_reply:'To Reply', newsletter_spam:'Newsletter-Spam', other:'Other' };
const byName = {};
for (const l of $('Get Gmail Labels').all().map(x => x.json)) if (l && l.name) byName[l.name.toLowerCase()] = l.id;
const results = $('Parse Classification').all().map(item => {
  const e = item.json;
  const labelName = prefix + NAMES[e.category];
  const id = byName[labelName.toLowerCase()];
  return { json: { ...e, labelName, wantLabels: [labelName], labelIds: id ? [id] : [], labelMissing: !id } };
});
const labelsToCreate = missingWithParents([...new Set(results.flatMap(r => r.json.wantLabels))], byName);
return results.map(r => ({ json: { ...r.json, labelsToCreate } }));

// One item per label to create, built once for the whole run (every item carries the same list).
const names = $input.first().json.labelsToCreate || [];
return names.map(name => ({ json: { name } }));

// Runs only after missing labels were created. Looks every label up again by name,
// so an "already exists" error from the create step is fine too.
const byName = {};
for (const l of $('Get Gmail Labels').all().concat($('Re-fetch Gmail Labels').all()).map(x => x.json)) if (l && l.name && l.id) byName[l.name.toLowerCase()] = l.id;
return $('Resolve Labels').all().map(item => {
  const e = item.json;
  const labelIds = e.wantLabels.map(n => byName[n.toLowerCase()]).filter(Boolean);
  return { json: { ...e, labelIds, labelMissing: !byName[e.labelName.toLowerCase()], labelsToCreate: [] } };
});
